function addLaplaceNoise(value, epsilon, sensitivity){
  const rnd = Math.random() - 0.5;
  const scale = sensitivity / epsilon;
  // simple Laplace sample using inverse CDF
  const noise = -scale * Math.sign(rnd) * Math.log(1 - 2 * Math.abs(rnd));
  return value + noise;
}
